export const BUILTIN_LIBRARY=BUILTIN_ROWS.map((r,i)=>({id:'builtin-'+i,field:r[0],group:r[1],name:r[2],hu:r[3],text:r[4],author:''}));
export function validateLibrary(raw){if(!raw||raw.schema!=='artoftomworks.scene-dna.library'||raw.version!==1||!Array.isArray(raw.entries)||raw.entries.length>200)throw Error('Invalid library.');const ids=new Set();return {schema:raw.schema,version:1,entries:raw.entries.map(e=>{if(!e||!LIBRARY_FIELDS.includes(e.field)||typeof e.id!=='string'||!/^custom-[\w-]{1,100}$/.test(e.id)||ids.has(e.id))throw Error('Invalid library entry.');ids.add(e.id);const out={id:e.id,field:e.field,group:e.field==='artist'?'artist':e.field==='profile'?'profile':'custom'};for(const key of ['name','text','author']){const v=e[key]||'';if(typeof v!=='string'||v.length>(key==='text'?2000:180))throw Error('Invalid entry text.');out[key]=v;}if(!out.name.trim()||!out.text.trim())throw Error('Name and text required.');out.hu=out.name;return out;})};}
export function libraryEntries(custom,field){return [...BUILTIN_LIBRARY,...custom.entries].filter(e=>e.field===field||(field==='style'&&e.field==='artist'));}
export function applySuggestion(current,entry,mode='append',includeAuthor=false){let text=entry.text;if(entry.author&&includeAuthor)text+=' Creative reference: '+entry.author+'.';const next=mode==='replace'||!current.trim()?text:current.trim()+'\n'+text;if(next.length>2000)throw Error('Field exceeds 2000 characters.');return next;}
